from collections import Counter
def f(I):
    bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            n=(a+dy,b+dx)
                            if 0<=n[0]<H and 0<=n[1]<W and not seen[n[0]][n[1]] and I[n[0]][n[1]]!=bg:
                                seen[n[0]][n[1]]=True; st.append(n)
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                col=I[min(cells)[0]][min(cells)[1]]
                comps.append((min(rs),max(rs),min(cs),max(cs),col))
    # sort: color desc, then row asc, then col asc
    comps.sort(key=lambda o:(-o[4],o[0],o[2]))
    res=[]
    for k,o in enumerate(comps):
        r=k//2; c=k%3
        res[r][c]=o[4]
    return [[0]*3 for _ in range(2)]+[res][0]
